('<lesson_id>', 'text', replace($blk${"html": "<p><img src=\"@@MEDIA@@shared/hello_rocket.webp\" alt=\"\" style=\"height:200px\"></p><h2>Привет-привет!</h2><p>Давай вспомним слова, которые ты изучал на уроке. Благодаря этому заданию ты точно их запомнишь. Вперёд 🏃‍♂️</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 0),
('<lesson_id>', 'flashcards', replace($blk${"cards": [{"text": "boring", "translation": "скучный", "audio_tts": "boring", "image": "@@MEDIA@@gg2/u4/boring.webp"}, {"text": "cheap", "translation": "дешёвый", "audio_tts": "cheap", "image": "@@MEDIA@@gg2/u4/cheap.webp"}, {"text": "dangerous", "translation": "опасный", "audio_tts": "dangerous", "image": "@@MEDIA@@gg2/u4/dangerous.webp"}, {"text": "difficult", "translation": "сложный", "audio_tts": "difficult", "image": "@@MEDIA@@gg2/u4/difficult.webp"}, {"text": "easy", "translation": "лёгкий", "audio_tts": "easy", "image": "@@MEDIA@@gg2/u4/easy.webp"}, {"text": "exciting", "translation": "увлекательный", "audio_tts": "exciting", "image": "@@MEDIA@@gg2/u4/exciting.webp"}, {"text": "expensive", "translation": "дорогой", "audio_tts": "expensive", "image": "@@MEDIA@@gg2/u4/expensive.webp"}, {"text": "high", "translation": "высокий", "audio_tts": "high", "image": "@@MEDIA@@gg2/u4/high.webp"}, {"text": "low", "translation": "низкий", "audio_tts": "low", "image": "@@MEDIA@@gg2/u4/low.webp"}, {"text": "safe", "translation": "безопасный", "audio_tts": "safe", "image": "@@MEDIA@@gg2/u4/safe.webp"}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 1),
('<lesson_id>', 'match', replace($blk${"title": "Соедини картинку со словом", "pairs": [{"left_image": "@@MEDIA@@gg2/u4/boring.webp", "right": "boring", "right_audio_tts": "boring"}, {"left_image": "@@MEDIA@@gg2/u4/cheap.webp", "right": "cheap", "right_audio_tts": "cheap"}, {"left_image": "@@MEDIA@@gg2/u4/dangerous.webp", "right": "dangerous", "right_audio_tts": "dangerous"}, {"left_image": "@@MEDIA@@gg2/u4/difficult.webp", "right": "difficult", "right_audio_tts": "difficult"}, {"left_image": "@@MEDIA@@gg2/u4/easy.webp", "right": "easy", "right_audio_tts": "easy"}, {"left_image": "@@MEDIA@@gg2/u4/exciting.webp", "right": "exciting", "right_audio_tts": "exciting"}, {"left_image": "@@MEDIA@@gg2/u4/expensive.webp", "right": "expensive", "right_audio_tts": "expensive"}, {"left_image": "@@MEDIA@@gg2/u4/high.webp", "right": "high", "right_audio_tts": "high"}, {"left_image": "@@MEDIA@@gg2/u4/low.webp", "right": "low", "right_audio_tts": "low"}, {"left_image": "@@MEDIA@@gg2/u4/safe.webp", "right": "safe", "right_audio_tts": "safe"}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 2),
('<lesson_id>', 'quiz', replace($blk${"questions": [{"q": "Как по-английски «скучный»?", "type": "single", "options": [{"text": "boring"}, {"text": "difficult"}, {"text": "exciting"}], "correct": [0]}, {"q": "Как по-английски «дешёвый»?", "type": "single", "options": [{"text": "easy"}, {"text": "cheap"}, {"text": "expensive"}], "correct": [1]}, {"q": "Как по-английски «опасный»?", "type": "single", "options": [{"text": "exciting"}, {"text": "high"}, {"text": "dangerous"}], "correct": [2]}, {"q": "Как по-английски «сложный»?", "type": "single", "options": [{"text": "difficult"}, {"text": "expensive"}, {"text": "low"}], "correct": [0]}, {"q": "Как по-английски «лёгкий»?", "type": "single", "options": [{"text": "high"}, {"text": "easy"}, {"text": "safe"}], "correct": [1]}, {"q": "Как по-английски «увлекательный»?", "type": "single", "options": [{"text": "low"}, {"text": "boring"}, {"text": "exciting"}], "correct": [2]}, {"q": "Как по-английски «дорогой»?", "type": "single", "options": [{"text": "expensive"}, {"text": "safe"}, {"text": "cheap"}], "correct": [0]}, {"q": "Как по-английски «высокий»?", "type": "single", "options": [{"text": "boring"}, {"text": "high"}, {"text": "dangerous"}], "correct": [1]}, {"q": "Как по-английски «низкий»?", "type": "single", "options": [{"text": "cheap"}, {"text": "difficult"}, {"text": "low"}], "correct": [2]}, {"q": "Как по-английски «безопасный»?", "type": "single", "options": [{"text": "safe"}, {"text": "dangerous"}, {"text": "easy"}], "correct": [0]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 3),
('<lesson_id>', 'text', replace($blk${"html": "<h3>Сравниваем! 🤹</h3><p>Настало время для новой домашней работы. Сегодня тебя ждёт одно интересное правило, которое ты прошёл на уроке, и несколько заданий, которые помогут его усвоить.</p><p>Начнём с видео: 1. Посмотри его. 2. Выбери персонажа, который понравился тебе больше всех, включи видео ещё раз и повторяй за своим героем :)</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 4),
('<lesson_id>', 'video', replace($blk${"title": "Посмотри видео и повторяй за своим героем", "url": "", "provider": "file"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 5),
('<lesson_id>', 'match', replace($blk${"title": "Соедини предложения с героем, который их произносил.", "pairs": [{"left": "Герой 1", "right": "You’re faster than me at juggling.", "right_audio_tts": "You're faster than me at juggling."}, {"left": "Герой 2", "right": "Yes, but I’m more surprising than you!", "right_audio_tts": "Yes, but I'm more surprising than you!"}, {"left": "Герой 3", "right": "I’m better than you at tricks.", "right_audio_tts": "I'm better than you at tricks."}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 6),
('<lesson_id>', 'text', replace($blk${"html": "<p>Тебя не проведёшь! А теперь посмотри на правило из конца видео:</p><p><img src=\"@@MEDIA@@gg2/u4/book_comparative_rule.webp\" alt=\"\" style=\"max-width:100%;max-height:360px;border-radius:12px\"></p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 7),
('<lesson_id>', 'match', replace($blk${"title": "Посмотри на правило. Соедини обычное слово с его сравнительной формой.", "pairs": [{"left": "big", "right": "bigger", "right_audio_tts": "bigger"}, {"left": "high", "right": "higher", "right_audio_tts": "higher"}, {"left": "exciting", "right": "more exciting", "right_audio_tts": "more exciting"}, {"left": "dangerous", "right": "more dangerous", "right_audio_tts": "more dangerous"}, {"left": "good", "right": "better", "right_audio_tts": "better"}, {"left": "bad", "right": "worse", "right_audio_tts": "worse"}, {"left": "low", "right": "lower", "right_audio_tts": "lower"}, {"left": "boring", "right": "more boring", "right_audio_tts": "more boring"}, {"left": "expensive", "right": "more expensive", "right_audio_tts": "more expensive"}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 8),
('<lesson_id>', 'text', replace($blk${"html": "<p>Великолепно! Следующее задание кажется простым, но будь внимателен. Расставь слова по порядку, чтобы получились предложения.</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 9),
