('<lesson_id>', 'order', replace($blk${"words": ["Winter", "weather", "is", "worse", "than", "summer", "weather."], "sentence": "Winter weather is worse than summer weather.", "audio_tts": "Winter weather is worse than summer weather."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 14),
('<lesson_id>', 'order', replace($blk${"words": ["Geography", "books", "are", "more", "interesting", "than", "Maths", "books."], "sentence": "Geography books are more interesting than Maths books.", "audio_tts": "Geography books are more interesting than Maths books."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 15),
('<lesson_id>', 'gaps', replace($blk${"title": "Прочитай разговор Джейка и Майкла и впиши правильную форму слова из скобок.", "mode": "type", "image": "@@MEDIA@@gg2/u4/jake_michael.webp", "text": "Jake: Let’s go swimming in the lake. The water today is __hotter__ (hot) than yesterday.\nMichael: No. Let’s go kayaking. It’s __more exciting__ (exciting) than swimming.\nJake: OK. Let’s get a kayak for two. Two people are __faster__ (fast) than one person.\nMichael: OK. And my arms are __longer__ (long) than your arms so I can help you.\nJake: What? That’s not true! My arms aren’t __shorter__ (short) than yours!\nMichael: Yes, they are. And I’m a __better__ (good) swimmer than you.\nJake: No, you aren’t. You are a __worse__ (bad) swimmer."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 16),
('<lesson_id>', 'task', replace($blk${"title": "Сравни мальчиков", "needs_review": true, "html": "<p>Задания становятся всё сложнее! Посмотри на картинку и сравни мальчиков. Составь четыре предложения.</p><p><img src=\"@@MEDIA@@gg2/u4/book_five_boys.webp\" alt=\"\" style=\"max-width:100%;max-height:300px;border-radius:12px\"></p><p><i>Пример: Tom is shorter than John.</i></p><p>Можешь использовать слова: young, old, happy, sad, tall, short, big (не забудь поставить их в правильную форму).</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 17),
('<lesson_id>', 'gaps', replace($blk${"title": "Какое слово пропущено? Подсказка — первая буква уже дана 😄", "mode": "type", "text": "1. The water in this bottle is c__older__ than the Arctic!\n2. Sailing is m__ore__ dangerous than cycling.\n3. I’m shorter t__han__ my brother.\n4. This bad painting is w__orse__ than that good painting.\n5. I can’t do my homework. It’s more d__ifficult__ than the lesson.\n6. He’s a better runner t__han__ you."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 18),
('<lesson_id>', 'quiz', replace($blk${"questions": [{"q": "Необязательное задание. Помоги лягушке добраться до берега: выбери слово, которое подходит картинке 🐸", "type": "single", "options": [{"text": "safe"}, {"text": "dangerous"}, {"text": "boring"}], "correct": [1], "image": "@@MEDIA@@gg2/u4/dangerous.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "expensive"}, {"text": "cheap"}], "correct": [0], "image": "@@MEDIA@@gg2/u4/expensive.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "difficult"}, {"text": "easy"}, {"text": "low"}], "correct": [1], "image": "@@MEDIA@@gg2/u4/easy.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "low"}, {"text": "high"}], "correct": [1], "image": "@@MEDIA@@gg2/u4/high.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "boring"}, {"text": "exciting"}, {"text": "safe"}], "correct": [1], "image": "@@MEDIA@@gg2/u4/exciting.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "cheap"}, {"text": "difficult"}], "correct": [1], "image": "@@MEDIA@@gg2/u4/difficult.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "safe"}, {"text": "dangerous"}], "correct": [0], "image": "@@MEDIA@@gg2/u4/safe.webp"}, {"q": "Какое слово подходит картинке?", "type": "single", "options": [{"text": "high"}, {"text": "expensive"}, {"text": "low"}], "correct": [2], "image": "@@MEDIA@@gg2/u4/low.webp"}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 19),
('<lesson_id>', 'text', replace($blk${"html": "<p><img src=\"@@MEDIA@@shared/well_done_trophy.webp\" alt=\"\" style=\"height:180px\"></p><h3>Ура! Домашняя работа выполнена.</h3><p>Наверное, пора отдохнуть :) Увидимся на занятии 😃</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 20)
